<?php $received = paid((int) $order['id']); ?><div class="print-area card receipt-card mx-auto php-receipt"><div class="receipt-header"><img src="/static/img/brand-star.svg" width="52" height="52" alt=""><div><strong class="receipt-shop-name"><?= e(SHOP_NAME)?></strong><p class="receipt-shop-meta mb-0"><?= e(SHOP_ADDRESS)?><br>+91 <?= e(SHOP_PHONE)?></p></div></div><div class="receipt-band"><?= t('Order receipt')?> <span><?= e($order['order_number'])?></span></div><div class="receipt-body"><p><?= e($order['customer_name'])?> · <?= e($order['customer_mobile'])?></p><p class="small"><?= t('Status')?>: <?= e($order['status'])?> · <?= t('Confirmed delivery date')?>: <?= e($order['confirmed_delivery_date'] ?: '—')?></p><div class="table-responsive"><table class="receipt-table"><thead><tr><th><?= t('Service')?></th><th><?= t('Qty')?></th><th class="text-end"><?= t('Amount')?></th></tr></thead><tbody><?php foreach ($items as $item) { ?><tr><td><?= e($item['service_name_snapshot'])?></td><td><?= (int) $item['quantity']?></td><td class="text-end"><?= money($item['line_total'])?></td></tr><?php } ?></tbody></table></div><div class="receipt-totals"><div class="row-line"><span><?= t('Stitching')?></span><span><?= money($order['subtotal_stitching'])?></span></div><div class="row-line"><span><?= t('Cloth')?></span><span><?= money($order['subtotal_material'])?></span></div><div class="row-line grand"><span><?= t('Grand total')?></span><span><?= money($order['grand_total'])?></span></div><div class="row-line paid"><span><?= t('Paid (verified)')?></span><span><?= money(decimal($received))?></span></div><div class="row-line balance"><span><?= t('Balance due')?></span><span><?= money(decimal(cents($order['grand_total']) - $received))?></span></div></div><p class="small text-secondary mt-4"><?= t('Stitching and cloth, billed separately.')?></p><button class="btn btn-primary no-print" data-print><?= t('Print receipt')?></button></div></div>
